INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Arbeitsteilung immer hierarchisch organisiert?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch funktional sein"}, {"text": "Ja", "correct": false, "because": "Nicht nur hierarchisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Arbeitsteilung?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Spezialisierung erhöht Produktivität"}, {"text": "Kostensenkung", "correct": false, "because": "Indirekter Effekt"}, {"text": "Teamgröße verringern", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formen der Arbeitsteilung gibt es?', 5, '[{"text": "Horizontale Arbeitsteilung", "correct": true, "because": "Aufgaben auf gleicher Ebene"}, {"text": "Vertikale Arbeitsteilung", "correct": true, "because": "Hierarchische Ebenen"}, {"text": "Technische Arbeitsteilung", "correct": false, "because": "Kein Standardbegriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsteilung fördert Spezialisierung. b) Sie führt immer zu mehr Kommunikation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kommunikation nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung von Arbeitsteilung?', 4, '[{"text": "Aufgabenkomplexität", "correct": false, "because": "Entscheidend für Aufteilung"}, {"text": "Mitarbeiterkompetenzen", "correct": false, "because": "Wichtig für Zuordnung"}, {"text": "Bürofarben", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitsteilung Koordination erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "Abstimmung nötig"}, {"text": "Nein", "correct": false, "because": "Koordination essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für eine horizontale Arbeitsteilung?', 3, '[{"text": "Aufgaben nach Funktion teilen", "correct": true, "because": "Gleiche Hierarchieebene"}, {"text": "Hierarchische Ebenen definieren", "correct": false, "because": "Vertikal"}, {"text": "Zufällige Zuweisung", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur vertikalen Arbeitsteilung?', 5, '[{"text": "Hierarchische Ebenen", "correct": true, "because": "Unterschiedliche Verantwortung"}, {"text": "Entscheidungsbefugnisse", "correct": true, "because": "Abstufung der Macht"}, {"text": "Gleiche Aufgaben", "correct": false, "because": "Horizontale Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitsteilung erhöht Produktivität. b) Sie führt immer zu mehr Fehlern. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehler nicht zwangsläufig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitsteilung unwichtig?', 4, '[{"text": "Koordination", "correct": false, "because": "Sichert Ablauf"}, {"text": "Kompetenzverteilung", "correct": false, "because": "Effizienzgrundlage"}, {"text": "Mitarbeiternamen", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Arbeitsteilung flexibel sein?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassbar an Bedarf"}, {"text": "Nein", "correct": false, "because": "Nicht starr"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt Arbeitsteilung?', 4, '[{"text": "Spezialisierung", "correct": true, "because": "Erhöht Effizienz"}, {"text": "Zeitersparnis", "correct": true, "because": "Parallele Arbeit"}, {"text": "Weniger Koordination", "correct": false, "because": "Koordination nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Arbeitsteilung nur in großen Firmen sinnvoll ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in kleinen Teams effektiv"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Arbeitsteilung?', 3, '[{"text": "Kompetenzen", "correct": true, "because": "Optimale Zuordnung"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Schnelligkeit", "correct": false, "because": "Effizienz wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsteilung reduziert Doppelarbeit. b) Sie erhöht immer den Aufwand.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aufwand nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Arbeitsteilung?', 5, '[{"text": "Koordinationsaufwand", "correct": true, "because": "Abstimmung nötig"}, {"text": "Abhängigkeit", "correct": true, "because": "Teaminterdependenz"}, {"text": "Schnellere Arbeit", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Arbeitsteilung unwichtig?', 3, '[{"text": "Aufgabenverteilung", "correct": false, "because": "Kernprinzip"}, {"text": "Teamkommunikation", "correct": false, "because": "Notwendig"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Arbeitsteilung die Qualität verbessern?', 3, '[{"text": "Ja", "correct": true, "because": "Spezialisierung steigert Kompetenz"}, {"text": "Nein", "correct": false, "because": "Oft positive Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Arbeitsteilung immer mehr Mitarbeiter erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in kleinen Teams möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Form wähle ich für eine horizontale Arbeitsteilung?', 4, '[{"text": "Fachliche Spezialisierung", "correct": true, "because": "Gleiche Ebene"}, {"text": "Hierarchische Trennung", "correct": false, "because": "Vertikal"}, {"text": "Zufällige Aufgaben", "correct": false, "because": "Ineffizient"}]');
